  (hp1 : ∑ j, p j = 1) (S : J → Matrix m s ℝ) {xs : n → ℝ} (hxs : A.mulVec xs = b) {lam : ℝ}
  (hlam : ∀ (v : n → ℝ), lam * v ⬝ᵥ v ≤ v ⬝ᵥ (NLAlib.SketchProject.expectedProjector A p S).mulVec v) (x : n → ℝ)
